sub(r"function target\(\)\{.*?\}\nfunction arrowToTarget",r'''function target(){if(world==='camp'&&mission===S.GOBLINS){const alive=goblins.find(g=>!g.dead);return alive||camp.returnPortal}if(world==='city'){if(mission===S.GO_GUILD||mission===S.RETURN_GUILD)return city.guildDoor;if(mission===S.PORTAL)return city.portal;if(mission===S.DONE&&currentCampaignMission())return orlaDeparture}if(world==='guild'){if(mission===S.REGISTER||mission===S.REPORT)return guild.reception;if(mission===S.CAPTAIN||mission===S.CAPTAIN_AFTER)return guild.captain;if(mission===S.BOARD)return guild.board;if(mission===S.PORTAL)return guild.exit}if(world==='orla'){const cm=currentCampaignMission(),pr=progressMain();if(cm==='mq_01')return orla.saira;if(cm==='mq_02')return orla.residents.find(r=>!(pr.rescued||[]).includes(r.id))||orla.saira;if(cm==='mq_03')return orla.clues.find(q=>!(pr.clues||[]).includes(q.id))||orla.ines;if(cm==='mq_04')return orla.cisternDoor;if(['mq_05','mq_06','mq_07','mq_08'].includes(cm))return roadDeparture;if(['mq_09','mq_10','mq_11','mq_12'].includes(cm))return quarryDeparture;if(['mq_13','mq_14','mq_15','mq_16','mq_17'].includes(cm))return gardenDeparture}if(world==='cistern'){const cm=currentCampaignMission(),pr=progressMain();if(cm==='mq_04'){const v=cistern.valves.find(v=>!(pr.valves||[]).includes(v.id));if(v)return v;return goblins.find(g=>!g.dead)||cistern.exit}}if(world==='road'){const cm=currentCampaignMission(),pr=progressMain();if(cm==='mq_05')return pr.metLio?road.firstGate:road.lio;if(cm==='mq_06'){const l=road.lanterns.find(x=>!(pr.lanterns||[]).includes(x.id));if(l)return l;return goblins.find(g=>!g.dead)||road.lio}if(cm==='mq_07')return road.manifests.find(m=>!(pr.manifests||[]).includes(m.id))||road.lio;if(cm==='mq_08')return goblins.find(g=>!g.dead)||road.finalGate}if(world==='quarry'){const cm=currentCampaignMission(),pr=progressMain();if(cm==='mq_09'){if(!pr.metAline)return quarry.aline;if(!pr.ledgerOpened)return quarry.ledger;return quarry.shiftCards.find(q=>!(pr.shiftCards||[]).includes(q.id))||quarry.aline}if(cm==='mq_10'){const b=quarry.brakes.find(x=>!(pr.brakes||[]).includes(x.id));if(b)return b;return goblins.find(g=>!g.dead)||quarry.aline}if(cm==='mq_11'){if(!pr.deep)return quarry.elevator;const w=quarry.workers.find(x=>!(pr.rescuedWorkers||[]).includes(x.id));return w||quarry.emergencyGate}if(cm==='mq_12')return goblins.find(g=>!g.dead)||quarry.bossPoint}if(world==='garden'){const cm=currentCampaignMission(),pr=progressMain();if(cm==='mq_13')return !pr.metNara?garden.nara:garden.samples.find(a=>!(pr.samples||[]).includes(a.id))||garden.nara;if(cm==='mq_14'){if(!pr.contractRead)return garden.contract;return garden.clauses.find(q=>!(pr.clauses||[]).includes(q.id))||garden.nara}if(cm==='mq_15'){const p=garden.plots.find(x=>!(pr.plots||[]).includes(x.id));if(p)return p;return goblins.find(g=>!g.dead)||garden.nara}if(cm==='mq_16'){const r=garden.commandRoots.find(x=>!(pr.commandRoots||[]).includes(x.id));if(r)return r;return goblins.find(g=>!g.dead)||garden.bossPoint}if(cm==='mq_17')return garden.returnGate}return null}
function arrowToTarget''','chapter4 targets')

insert_draw=r'''function drawGardenDepartureMarker(){const cm=currentCampaignMission();if(!['mq_13','mq_14','mq_15','mq_16','mq_17'].includes(cm))return;ctx.fillStyle='#45623e';ctx.fillRect(gardenDeparture.x-48,gardenDeparture.y-25,96,50);ctx.fillStyle='#93b36c';ctx.fillRect(gardenDeparture.x+33,gardenDeparture.y-67,9,45);label('JARDIM SUSPENSO',gardenDeparture.x-72,gardenDeparture.y-76,'#d8efb2',13)}
function drawGarden(){ctx.fillStyle='#203126';ctx.fillRect(0,0,garden.w,garden.h);ctx.fillStyle='#355239';for(let x=120;x<1820;x+=190){ctx.fillRect(x,110,130,90);ctx.fillStyle='#6b8b53';ctx.beginPath();ctx.arc(x+65,95,34,0,Math.PI*2);ctx.fill();ctx.fillStyle='#355239'}ctx.fillStyle='#526a43';ctx.fillRect(390,470,1150,210);label('JARDIM SUSPENSO',720,76,'#d8efb2',21);label('Retorno a Orla',55,802,'#ddd');const cm=currentCampaignMission(),pr=progressMain();npc(garden.nara.x,garden.nara.y,'Nara Reis','#a8c27f',cm==='mq_13'&&(!pr.metNara||(pr.samples||[]).length>=3)||cm==='mq_14'&&pr.contractRead&&(pr.clauses||[]).length>=3);if(cm==='mq_13')for(const a of garden.samples){const done=(pr.samples||[]).includes(a.id);ctx.fillStyle=done?'#55735b':'#8fbf73';ctx.beginPath();ctx.arc(a.x,a.y,18,0,Math.PI*2);ctx.fill();if(!done)label(a.name,a.x-45,a.y-30,'#d9efc1')}ctx.fillStyle='#c2aa78';ctx.fillRect(garden.contract.x-22,garden.contract.y-16,44,32);if(cm==='mq_14')label('Contrato original',garden.contract.x-48,garden.contract.y-28,'#ecd8a6');if(cm==='mq_14'&&pr.contractRead)for(const q of garden.clauses){const done=(pr.clauses||[]).includes(q.id);ctx.fillStyle=done?'#65775d':'#c8b78d';ctx.fillRect(q.x-14,q.y-10,28,20);if(!done)label(q.name,q.x-50,q.y-22,'#ead7ad')}if(cm==='mq_15')for(const p of garden.plots){const done=(pr.plots||[]).includes(p.id);ctx.fillStyle=done?'#7cab66':'#9c7048';ctx.fillRect(p.x-38,p.y-28,76,56);label(done?'Lote protegido':'Lote de sementes',p.x-48,p.y-40,done?'#c9efb8':'#e7c394')}if(cm==='mq_16')for(const r of garden.commandRoots){const done=(pr.commandRoots||[]).includes(r.id);ctx.strokeStyle=done?'#6d8b63':'#b66c55';ctx.lineWidth=10;ctx.beginPath();ctx.moveTo(r.x-45,r.y+40);ctx.quadraticCurveTo(r.x,r.y-40,r.x+45,r.y+35);ctx.stroke();ctx.lineWidth=1;if(!done)label('Raiz de comando',r.x-48,r.y-52,'#f0b89f')}for(const g of goblins){if(g.dead)continue;if(g.state==='windup'){ctx.fillStyle='#d33a';ctx.beginPath();ctx.arc(g.attackX,g.attackY,g.gardenBoss?70:52,0,Math.PI*2);ctx.fill();ctx.strokeStyle='#ff6565';ctx.stroke()}ctx.fillStyle=g.gardenBoss?'#8a5472':'#627d4b';ctx.beginPath();ctx.arc(g.x,g.y,g.r,0,Math.PI*2);ctx.fill();label(g.name||'Raiz Intrusa',g.x-(g.gardenBoss?64:42),g.y-g.r-12,g.gardenBoss?'#f3bad7':'#d5e9b8',g.gardenBoss?15:12);ctx.fillStyle='#222';ctx.fillRect(g.x-42,g.y+g.r+9,84,6);ctx.fillStyle='#b84b4b';ctx.fillRect(g.x-42,g.y+g.r+9,84*g.hp/g.maxHp,6)}}
'''
